declare sid text; sec text;
begin
  select id, coalesce((select x->>'id' from jsonb_array_elements(coalesce(sections,'[]'::jsonb)) x where x->>'kind'='test' order by (x->>'name' ilike '%тест%') desc limit 1),'tests')
    into sid, sec from public.subjects where name ilike 'Математика%' order by length(name) limit 1;
  if sid is null then raise exception 'Математика пәні табылмады'; end if;
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, 'Нұсқа 1 · Велосипед', '[{"q": "Теңдеуді шешіңіз: (x+8)/(x+5) + (2x+7)/(x+5) = 3", "options": ["A) (−∞; −5) ∪ (−5; +∞)", "B) (−∞; 3) ∪ (3; +∞)", "C) ∅", "D) −5"], "answer": 0}, {"q": "Есептеңіз: (3⁶·7¹³)/21⁸ · (7/3)⁻⁴", "options": ["A) 147", "B) 441", "C) 21", "D) 63"], "answer": 3}, {"q": "(2+√3)/(2−√3) − (4√3+7) өрнегін ықшамдап, жауабын табыңыз", "options": ["A) Оң сан", "B) Бүтін сан", "C) Теріс сан", "D) Иррационал сан"], "answer": 1}, {"q": "Тікбұрышты үшбұрыштың катеттері 20 см және 21 см. Үлкен катетінің гипотенузаға түсірілген проекциясының ұзындығын табыңыз", "options": ["A) 20/29", "B) 21/29", "C) 400/29", "D) 441/29"], "answer": 3}, {"q": "Теңсіздікті шешіңіз: (x² − 5x + 6)·√(x+4) < 0", "options": ["A) ∅", "B) x ∈ (−4; 3)", "C) x ∈ (−4; 2) ∪ (3; +∞)", "D) x ∈ (2; 3)"], "answer": 3}, {"q": "Дұрыс төртбұрышты қиық пирамиданың табан қабырғалары 2 см және 4 см, ал бүйір қыры √11-ге тең. Пирамиданың көлемін табыңыз.", "options": ["A) 28", "B) 42", "C) 24", "D) 27"], "answer": 0}, {"q": "Егер 0 < a < 1 болса, y = logₐx функциясының графигін табыңыз", "options": ["A", "B", "C", "D"], "answer": 0, "img": "img/math/v1_07.jpg"}, {"q": "f(x) = (2/3)·cos(12x + 7) + 8 функциясының екінші ретті туындысын табыңыз", "options": ["A) 96cos(12x + 7)", "B) 96sin(12x + 7)", "C) −96cos(12x + 7)", "D) −96sin(12x + 7)"], "answer": 2}, {"q": "Боялған бөліктің ауданын табыңыз", "options": ["A) 9", "B) 8", "C) 10⅔", "D) 11⅓"], "answer": 0, "img": "img/math/v1_09.jpg"}, {"q": "Теңдеуді шешіңіз: arccos²(x) − 6arccos(x) + 8 = 0", "options": ["A) −cos2", "B) cos2", "C) cos4", "D) −cos4"], "answer": 1}, {"q": "Марат қосындысы 12-ге тең екі сан ойлады. Егер төрт еселенген бірінші сан үш еселенген екінші саннан 1-ге кем болса, осы сандардың айырмасының квадратын табыңыз", "options": ["A) 7", "B) 5", "C) 4", "D) 24"], "answer": 2}, {"q": "Өрнектің мәнін табыңыз: (2,6² − 5,2·7,5 + 7,5²) / (2,5² − 2,4²)", "options": ["A) 49", "B) 4,9", "C) 0,49", "D) 490"], "answer": 0}, {"q": "Арифметикалық прогрессияның a₃ + a₁₆ = 31 болса, алғашқы он сегіз мүшесінің қосындысын табыңыз", "options": ["A) 248", "B) 310", "C) 270", "D) 279"], "answer": 3}, {"q": "Центрі O(−2; 3; 4) нүктесі болатын және абсцисса осін жанайтын сфера теңдеуін жазыңыз", "options": ["A) x² + y² + z² + 4x − 6y − 8z − 4 = 0", "B) x² + y² + z² + 4x + 6y + 8z + 4 = 0", "C) x² + y² + z² + 4x − 6y − 8z + 4 = 0", "D) x² + y² + z² − 4x + 6y − 8z − 4 = 0"], "answer": 2}, {"q": "Теңдеудің түбірлерінің қосындысын табыңыз: logₓ(11·x^(lg x) − 10) = 2lg(x)", "options": ["A) 10,1", "B) 11,1", "C) 10", "D) 11"], "answer": 0}, {"q": "Төмендегі функциялардың ішінен жұп функциясын көрсетіңіз", "options": ["A) f(x) = (x⁵ + x³) / tg(2x)", "B) f(x) = (x⁷ + x³) / cos(3x)", "C) f(x) = (x⁴ − x³) / ctg(x)", "D) f(x) = (x⁴ + x²) / sin(2x)"], "answer": 0}, {"q": "log₁/ₓ(3x − 4) + 2 = log₃ₓ₋₄(x) теңдеуінің түбірі x₀ болса, log₈(x₀) өрнегінің мәнін табыңыз", "options": ["A) −3", "B) 1/3", "C) 3", "D) −1/3"], "answer": 1}, {"q": "Градуспен берілген 1050° бұрышты радианмен көрсетіңіз", "options": ["A) 35π/2", "B) 35π/6", "C) 35π/9", "D) 35π/3"], "answer": 1}, {"q": "Табан аудандары 9π см² және 64π см² қиық конустың жасаушысы 13 см. Конустың биіктігін табыңыз", "options": ["A) 5", "B) 10", "C) 12", "D) 11"], "answer": 2}, {"q": "Шеңбердің ішінде орналасқан нүктеден шеңберге дейінгі ең үлкен және ең кіші қашықтықтар сәйкесінше 12 см және 3 см. Осы нүкте арқылы диаметрге перпендикуляр хорда жүргізілді. Хорданың ұзындығын табыңыз", "options": ["A) 6", "B) 10", "C) 8", "D) 12"], "answer": 3}, {"q": "A = (1/∜x)^(−4√x) және B = x^(∛x) сандарын салыстырыңыз", "options": ["A) A > B", "B) A = B", "C) A < B", "D) A⁻¹ = B"], "answer": 0}, {"q": "{ log₃x = y ; x^(y/4) = 3 } теңдеулер жүйесінің барлық түбірлерінің қосындысы жатқан аралықты табыңыз", "options": ["A) [−2; 9]", "B) (−2; 2)", "C) [2; 9]", "D) (2; 10)"], "answer": 3}, {"q": "4^(3x−5) > 0,125 теңсіздігінің шешімі болатын ең кіші бүтін санды табыңыз", "options": ["A) 1", "B) 2", "C) 3", "D) 0"], "answer": 1}, {"q": "{ log₃²x < 4 ; log₃(4x) > 2 } теңсіздіктер жүйесін қанағаттандыратын бүтін сандардың санын табыңыз", "options": ["A) 6", "B) 7", "C) 5", "D) 4"], "answer": 0}, {"q": "Есептеңіз: √( √(34² − 30²) / 0,25 )", "options": ["A) 0,8", "B) 2", "C) 8", "D) 4"], "answer": 2}, {"q": "Мәтін (№26–30, Велосипед): Велосипед дөңгелегінің диаметрі 70 см. Бұл велосипедтің жылдамдық ауыстыру жүйесі 9 түрлі передачадан (жылдамдық ауыстырғыш) тұрады. 1-передача ең баяу қозғалысты қамтамасыз етеді. Бұл кезде шынжыр алдыңғы ең кіші жұлдызшада, ал артқы ең үлкен жұлдызшада орналасады. 9-передача ең жоғары жылдамдықпен жүруге мүмкіндік береді. Бұл кезде шынжыр алдыңғы ең үлкен жұлдызшада, ал артқы ең кіші жұлдызшада болады. Алдыңғы жұлдызшалар педальмен, ал артқы жұлдызшалар жетекші дөңгелекпен (артқы дөңгелекпен) тікелей байланысқан. Алдыңғы жұлдызшалардың тістер саны: үлкені – 44, ортаңғысы – 32, кішісі – 24. Артқы жұлдызшалар кассетасындағы негізгі жұлдызшалардың тістер саны: үлкені – 36, ортаңғыларының бірі – 16, ең кішісі – 14. (π = 3)\n\nАлдыңғы үлкен жұлдызша 7 рет айналғанда артқы жұлдызша неше рет айналады", "options": ["A) 36", "B) 32", "C) 22", "D) 14"], "answer": 2}, {"q": "Мәтін (№26–30, Велосипед): Велосипед дөңгелегінің диаметрі 70 см. Бұл велосипедтің жылдамдық ауыстыру жүйесі 9 түрлі передачадан (жылдамдық ауыстырғыш) тұрады. 1-передача ең баяу қозғалысты қамтамасыз етеді. Бұл кезде шынжыр алдыңғы ең кіші жұлдызшада, ал артқы ең үлкен жұлдызшада орналасады. 9-передача ең жоғары жылдамдықпен жүруге мүмкіндік береді. Бұл кезде шынжыр алдыңғы ең үлкен жұлдызшада, ал артқы ең кіші жұлдызшада болады. Алдыңғы жұлдызшалар педальмен, ал артқы жұлдызшалар жетекші дөңгелекпен (артқы дөңгелекпен) тікелей байланысқан. Алдыңғы жұлдызшалардың тістер саны: үлкені – 44, ортаңғысы – 32, кішісі – 24. Артқы жұлдызшалар кассетасындағы негізгі жұлдызшалардың тістер саны: үлкені – 36, ортаңғыларының бірі – 16, ең кішісі – 14. (π = 3)\n\nАртқы үлкен жұлдызша 4 рет айналғанда алдыңғы жұлдызша неше рет айналады", "options": ["A) 6", "B) 3", "C) 8", "D) 5"], "answer": 0}, {"q": "Мәтін (№26–30, Велосипед): Велосипед дөңгелегінің диаметрі 70 см. Бұл велосипедтің жылдамдық ауыстыру жүйесі 9 түрлі передачадан (жылдамдық ауыстырғыш) тұрады. 1-передача ең баяу қозғалысты қамтамасыз етеді. Бұл кезде шынжыр алдыңғы ең кіші жұлдызшада, ал артқы ең үлкен жұлдызшада орналасады. 9-передача ең жоғары жылдамдықпен жүруге мүмкіндік береді. Бұл кезде шынжыр алдыңғы ең үлкен жұлдызшада, ал артқы ең кіші жұлдызшада болады. Алдыңғы жұлдызшалар педальмен, ал артқы жұлдызшалар жетекші дөңгелекпен (артқы дөңгелекпен) тікелей байланысқан. Алдыңғы жұлдызшалардың тістер саны: үлкені – 44, ортаңғысы – 32, кішісі – 24. Артқы жұлдызшалар кассетасындағы негізгі жұлдызшалардың тістер саны: үлкені – 36, ортаңғыларының бірі – 16, ең кішісі – 14. (π = 3)\n\nАлдыңғы ортаңғы жұлдызша 5 рет айналғанда артқы жұлдызша неше айналым жасайды", "options": ["A) 12", "B) 10", "C) 11", "D) 8"], "answer": 1}, {"q": "Мәтін (№26–30, Велосипед): Велосипед дөңгелегінің диаметрі 70 см. Бұл велосипедтің жылдамдық ауыстыру жүйесі 9 түрлі передачадан (жылдамдық ауыстырғыш) тұрады. 1-передача ең баяу қозғалысты қамтамасыз етеді. Бұл кезде шынжыр алдыңғы ең кіші жұлдызшада, ал артқы ең үлкен жұлдызшада орналасады. 9-передача ең жоғары жылдамдықпен жүруге мүмкіндік береді. Бұл кезде шынжыр алдыңғы ең үлкен жұлдызшада, ал артқы ең кіші жұлдызшада болады. Алдыңғы жұлдызшалар педальмен, ал артқы жұлдызшалар жетекші дөңгелекпен (артқы дөңгелекпен) тікелей байланысқан. Алдыңғы жұлдызшалардың тістер саны: үлкені – 44, ортаңғысы – 32, кішісі – 24. Артқы жұлдызшалар кассетасындағы негізгі жұлдызшалардың тістер саны: үлкені – 36, ортаңғыларының бірі – 16, ең кішісі – 14. (π = 3)\n\nВелосипедші 1-передачамен педальді 18 рет айналдырғанда велосипед қанша метрге орын ауыстырды", "options": ["A) 12 м", "B) 24 м", "C) 25,2 м", "D) 37,8 м"], "answer": 2}, {"q": "Мәтін (№26–30, Велосипед): Велосипед дөңгелегінің диаметрі 70 см. Бұл велосипедтің жылдамдық ауыстыру жүйесі 9 түрлі передачадан (жылдамдық ауыстырғыш) тұрады. 1-передача ең баяу қозғалысты қамтамасыз етеді. Бұл кезде шынжыр алдыңғы ең кіші жұлдызшада, ал артқы ең үлкен жұлдызшада орналасады. 9-передача ең жоғары жылдамдықпен жүруге мүмкіндік береді. Бұл кезде шынжыр алдыңғы ең үлкен жұлдызшада, ал артқы ең кіші жұлдызшада болады. Алдыңғы жұлдызшалар педальмен, ал артқы жұлдызшалар жетекші дөңгелекпен (артқы дөңгелекпен) тікелей байланысқан. Алдыңғы жұлдызшалардың тістер саны: үлкені – 44, ортаңғысы – 32, кішісі – 24. Артқы жұлдызшалар кассетасындағы негізгі жұлдызшалардың тістер саны: үлкені – 36, ортаңғыларының бірі – 16, ең кішісі – 14. (π = 3)\n\nВелосипедші 9-передачамен 46,2 м жол жүруі үшін педальді неше рет айналдырады", "options": ["A) 6", "B) 5", "C) 8", "D) 7"], "answer": 3}, {"q": "(2x − 3y)² = Px² + Qxy + Ry² тепе-теңдігінен P, Q, R коэффициенттерін анықтап, төмендегі өрнектердің мәндерін сәйкестендіріңіз", "left": ["A) P + Q + R", "B) 3P + Q − R"], "options": ["−9", "−1", "1", "9"], "pairs": [2, 0]}, {"q": "(x² + 2x + 3)/(x + 2) − (6x + 12)/(x² + 2x + 3) = 5 теңдеуінің нақты түбірлерінің қосындысы мен көбейтіндісін сәйкестендіріңіз", "left": ["A) түбірлерінің көбейтіндісі", "B) түбірлерінің қосындысы"], "options": ["9", "−9", "4"], "pairs": [1, 2]}, {"q": "Радиусы 6 см шеңберге сырттай сызылған трапецияның бүйір қабырғасы 13 см. ABC және ADC үшбұрыштарының аудандарын дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A) S(ABC)", "B) S(ADC)"], "options": ["108", "117", "52", "48"], "pairs": [3, 0]}, {"q": "Ордината осіне қарағанда симметриялы және координаталар басына қарағанда симметриялы функцияларды дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A) координаталар басына қарағанда симметриялы функция", "B) ордината осіне қарағанда симметриялы функция"], "options": ["жұп", "периодты", "тақ", "жалпы түрдегі функция"], "pairs": [2, 0]}, {"q": "100 мүшеден тұратын арифметикалық прогрессия құрайтын тізбектің алғашқы үш мүшесінің қосындысы 15-ке, ал соңғы үш мүшесінің қосындысы 888-ге тең. Төмендегі өрнектерді мәндерімен сәйкестендіріңіз", "left": ["A) a₄₉", "B) a₅₀"], "options": ["155", "152", "149", "146"], "pairs": [3, 2]}, {"q": "cos20° − 2sin35°·sin55° өрнегінің мәнін табыңыз", "options": ["A) 1", "B) 1/2", "C) 2cos20°", "D) 0", "E) 2sin20°", "F) √3/2"], "answers": [3]}, {"q": "Геометриялық прогрессияның алғашқы төрт мүшесінің қосындысы 45-ке тең, келесі төрт мүшесінің қосындысы 720. Осы прогрессияның алғашқы тоғыз мүшесінің қосындысының модулінің мүмкін мәндерін табыңыз", "options": ["A) 1533", "B) 1539", "C) 1536", "D) 1530", "E) 1531", "F) 1542"], "answers": [0, 1]}, {"q": "M(1; −8) нүктесі арқылы өтетін y = 2x² − 3x − 7 функциясына жүргізілген жанама теңдеуінің көлбеулік бұрышын табыңыз", "options": ["A) π/3", "B) 135°", "C) π/4", "D) 45°", "E) 60°", "F) 3π/4"], "answers": [2, 3]}, {"q": "Дұрыс төртбұрышты қиық пирамиданың табан аудандары 4 см² және 16 см². Егер бүйір қыры √5-ке тең болса, биіктігінің сан мәні жататын аралықт(-ард)ы табыңыз", "options": ["A) (0; 1,2)", "B) (1,5; 3)", "C) (0; 1,4)", "D) (1; 3]", "E) (0; 2)", "F) (2; 3]"], "answers": [1, 3, 4]}]'::jsonb, now() + interval '0 second');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, 'Нұсқа 2 · Шолу дөңгелегі (Колесо обозрения)', '[{"q": "(8a⁻⁵b⁷c³)/(3a⁻⁸b⁹c²) · (6bc⁴)/(2a⁻¹b⁻²c⁶) өрнекті ықшамдаңыз және a = 2, b = 3, c = 4 болғанда мәнін табыңыз", "options": ["A) 32", "B) 48", "C) 96", "D) 384"], "answer": 2}, {"q": "y = arccos4x функциясының туындысын табыңыз", "options": ["A) 1/√(1−4x²)", "B) −4/√(1−16x²)", "C) 4/√(1−16x²)", "D) −1/√(1−4x²)"], "answer": 1}, {"q": "Координаталық жазықтықтың суретте көрсетілген нүктелер жиынын беретін теңсіздікті табыңыз", "options": ["A) y ≥ 2x² − 20x + 48", "B) y ≤ x² − 10x + 23", "C) y ≥ x² − 10x + 23", "D) y ≤ 2x² − 20x + 48"], "answer": 3, "img": "img/math/v2_03.jpg"}, {"q": "tg²x = 169 теңдеуді шешіңіз", "options": ["A) x = ±arctg13 + πn", "B) x = arctg169 + πn", "C) x = −arctg169 + πn", "D) x = arctg14 + πn"], "answer": 0}, {"q": "x^(log₅x − 3) = 625 теңдеудің түбірлерінің көбейтіндісін табыңыз", "options": ["A) 25", "B) 125", "C) 1/5", "D) 625"], "answer": 1}, {"q": "y = 1/(2x − 4) + 5 функциясына кері функцияны табыңыз", "options": ["A) y = 1/(2x − 10) + 2", "B) y = 1/(x − 5) + 4", "C) y = 1/(2x − 10) + 5", "D) y = 1/(x − 5) + 2"], "answer": 0}, {"q": "2026 + 4cos(π/2 − α)·sin(π + α) + 4cos(π + α)·sin(π/2 − α) өрнектің мәнін табыңыз", "options": ["A) 2018", "B) 2030", "C) 2022", "D) 2034"], "answer": 2}, {"q": "A(2; 1; 3), B(−2; 6; 5) нүктелері арқылы өтетін түзудің канондық теңдеуін табыңыз", "options": ["A) (x+2)/(−4) = (y−1)/5 = (z−3)/2", "B) (x+2)/(−4) = (y−6)/5 = (z+5)/2", "C) (x+2)/(−4) = (y−6)/5 = (z−5)/2", "D) (x−2)/(−4) = (y−1)/5 = (z−3)/2"], "answer": 2}, {"q": "∛(7 + √22) · ∛(7 − √22) есептеңіз", "options": ["A) 3", "B) 3√3", "C) −∛15", "D) −3"], "answer": 0}, {"q": "(1/3)·sin(arccos(5/13)) мәнін табыңыз", "options": ["A) 12/13", "B) 3/13", "C) 5/39", "D) 4/13"], "answer": 3}, {"q": "{ log₁/₂₀₂₆ x > log₁/₂₀₂₆ (6 − 2x) ; lg x < 1 } теңсіздіктер жүйесін қанағаттандыратын бүтін сандардың санын табыңыз", "options": ["A) 1", "B) 2", "C) 3", "D) 4"], "answer": 0}, {"q": "x|x| − 2|x| − 3 = 0 теңдеудің түбірінің еселігін табыңыз", "options": ["A) 10", "B) 6", "C) 8", "D) 4"], "answer": 1}, {"q": "y = −3x² − 2 функция графигі қандай ширектерде орналасқан", "options": ["A) I, IV", "B) II, III", "C) I, II", "D) III, IV"], "answer": 3}, {"q": "(x + 4)(x + 3)(x + 2)(x + 1) = 120 теңдеуінің нақты түбірлерінің көбейтіндісін табыңыз", "options": ["A) −96", "B) 25", "C) −6", "D) 16"], "answer": 2}, {"q": "ABC тікбұрышты үшбұрышының AB катеті 12, AC катеті тең үш бөлікке бөлінген. Егер BD = 13 болса, BC – гипотенузаны табыңыз", "options": ["A) 3√40", "B) 20", "C) √369", "D) 11√3"], "answer": 2, "img": "img/math/v2_15.jpg"}, {"q": "4x/(√5 + 3) иррационалдықтан арылтыңыз", "options": ["A) 3x − √5x", "B) 12x − 4√5x", "C) 3x + √5x", "D) 12x + 4√5x"], "answer": 0}, {"q": "log₂ₓ₊₁(x + 2) + 2·log_(x²+4x+4)(2x + 1) = 2 теңдеуінің түбірі қандай сан болады", "options": ["A) ондық бөлшек", "B) натурал сан", "C) теріс сан", "D) оң сан да, теріс сан да емес"], "answer": 1}, {"q": "y = 4sin(tg(2x − 1)²) функциясының туындысын табыңыз", "options": ["A) −16(2x−1)·cos(tg(2x−1)²) / cos²(2x−1)²", "B) 16(2x−1)·cos(tg(2x−1)²) / cos²(2x−1)²", "C) 16(2x−1)·cos(ctg(2x−1)²) / sin²(2x−1)²", "D) 16(2x−1)·cos(tg(2x−1)²) / sin²(2x−1)²"], "answer": 1}, {"q": "Суретте берілген ABCDA₁B₁C₁D₁ параллелепипедтің E және K нүктелері жақтарының диагональдарының қиылысу нүктелері. KE векторының координаталарының қосындысын табыңыз", "options": ["A) −5", "B) 9", "C) 5", "D) −1"], "answer": 3, "img": "img/math/v2_19.jpg"}, {"q": "2sin²x ≥ 1 теңсіздікті шешіңіз", "options": ["A) [π/4 + πn; 3π/4 + πn], n∈Z", "B) [π/4 + 2πn; 3π/4 + 2πn], n∈Z", "C) [−π/4 + 2πn; π/4 + 2πn], n∈Z", "D) [−3π/4 + 2πn; −π/4 + 2πn], n∈Z"], "answer": 0}, {"q": "{ 5cosx − cosy = 0 ; 3sinx − siny − 2 = 0 } теңдеулер жүйесін шешіңіз", "options": ["A) (2πn; π/2 + 2πn), n∈Z", "B) (π/2 + 2πn; 2πn), n∈Z", "C) (π/2 + 2πn; π/2 + 2πn), n∈Z", "D) (π/4 + 2πn; π/4 + 2πn), n∈Z"], "answer": 2}, {"q": "Сыртқы бұрышы 36°-қа тең дұрыс көпбұрыштың қабырғасы 5 см. Периметрін табыңыз", "options": ["A) 50", "B) 40", "C) 30", "D) 60"], "answer": 0}, {"q": "(tg15°·cos30°)/(1 + tg²15°) өрнектің мәнін табыңыз", "options": ["A) 1/4", "B) √3/4", "C) 1/2", "D) √3/8"], "answer": 3}, {"q": "y = x² − 5x функциясына жүргізілген жанама y = 3x + 1 түзуіне параллель. Жанаманың теңдеуін табыңыз", "options": ["A) y = 3x − 4", "B) y = 3x − 16", "C) y = 3x + 5", "D) y = 3x + 11"], "answer": 1}, {"q": "log₃(4 − 3⁻ˣ) = x + 1 теңдеудің түбірлерінің қосындысын табыңыз", "options": ["A) 0", "B) 1", "C) −1", "D) 1/3"], "answer": 2}, {"q": "Мәтін (№26–30, Шолу дөңгелегі): Саябаққа келушілерге арналып жаңа шолу дөңгелегі орнатылды. Аттракционның құрылымы өзара центрлес екі үлкен және кіші шеңберлі темір қаңқадан тұрады. Сыртқы үлкен шеңбердің диаметрі 40 м, ал ішкі кіші шеңбердің диаметрі 24 м. Дөңгелектің сыртқы жиегінде өзара бірдей қашықтықта орналасқан 20 кабина бар. AC = BC, BAC бұрышы 72° және cos18° ≈ 0,96.\n\nШолу дөңгелегінің көршілес екі кабинасына баратын тіреуіштер (радиустар) арасындағы α бұрышының градустық өлшемін табыңыз", "img": "img/math/v2_ctx.jpg", "options": ["A) 15°", "B) 18°", "C) 20°", "D) 24°"], "answer": 1}, {"q": "Мәтін (№26–30, Шолу дөңгелегі): Саябаққа келушілерге арналып жаңа шолу дөңгелегі орнатылды. Аттракционның құрылымы өзара центрлес екі үлкен және кіші шеңберлі темір қаңқадан тұрады. Сыртқы үлкен шеңбердің диаметрі 40 м, ал ішкі кіші шеңбердің диаметрі 24 м. Дөңгелектің сыртқы жиегінде өзара бірдей қашықтықта орналасқан 20 кабина бар. AC = BC, BAC бұрышы 72° және cos18° ≈ 0,96.\n\nAB доғасының ұзындығын табыңыз (π ≈ 3)", "img": "img/math/v2_ctx.jpg", "options": ["A) 12", "B) 3,6", "C) 6", "D) 7,2"], "answer": 2}, {"q": "Мәтін (№26–30, Шолу дөңгелегі): Саябаққа келушілерге арналып жаңа шолу дөңгелегі орнатылды. Аттракционның құрылымы өзара центрлес екі үлкен және кіші шеңберлі темір қаңқадан тұрады. Сыртқы үлкен шеңбердің диаметрі 40 м, ал ішкі кіші шеңбердің диаметрі 24 м. Дөңгелектің сыртқы жиегінде өзара бірдей қашықтықта орналасқан 20 кабина бар. AC = BC, BAC бұрышы 72° және cos18° ≈ 0,96.\n\nAB кесіндісінің ұзындығын табыңыз (π ≈ 3)", "img": "img/math/v2_ctx.jpg", "options": ["A) 4√2", "B) 5√2", "C) 3√2", "D) 6√2"], "answer": 0}, {"q": "Мәтін (№26–30, Шолу дөңгелегі): Саябаққа келушілерге арналып жаңа шолу дөңгелегі орнатылды. Аттракционның құрылымы өзара центрлес екі үлкен және кіші шеңберлі темір қаңқадан тұрады. Сыртқы үлкен шеңбердің диаметрі 40 м, ал ішкі кіші шеңбердің диаметрі 24 м. Дөңгелектің сыртқы жиегінде өзара бірдей қашықтықта орналасқан 20 кабина бар. AC = BC, BAC бұрышы 72° және cos18° ≈ 0,96.\n\nШолу дөңгелегіне отыру құны адам басына 1200 тг. Жұмыс күндері әр кабинада 4 адам, ал демалыс (сенбі, жексенбі) күндері 9 адамнан отырады. Осы айда толық 4 апта және 3 жұмыс күні болса, орташа айлық табысты табыңыз", "img": "img/math/v2_ctx.jpg", "options": ["A) 3780000 тг", "B) 39870000 тг", "C) 3200000 тг", "D) 3936000 тг"], "answer": 3}, {"q": "Мәтін (№26–30, Шолу дөңгелегі): Саябаққа келушілерге арналып жаңа шолу дөңгелегі орнатылды. Аттракционның құрылымы өзара центрлес екі үлкен және кіші шеңберлі темір қаңқадан тұрады. Сыртқы үлкен шеңбердің диаметрі 40 м, ал ішкі кіші шеңбердің диаметрі 24 м. Дөңгелектің сыртқы жиегінде өзара бірдей қашықтықта орналасқан 20 кабина бар. AC = BC, BAC бұрышы 72° және cos18° ≈ 0,96.\n\nABC үшбұрышының периметрін табыңыз", "img": "img/math/v2_ctx.jpg", "options": ["A) 127√2/7", "B) 125√2/7", "C) 128√2/7", "D) 175√2/7"], "answer": 2}, {"q": "y = 3(x + 2)(x + a) функциясы жұп функция болса, a-ның мәнін және функцияның ең кіші мәнін дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A) a", "B) y_min"], "options": ["−4", "−12", "2", "−2"], "pairs": [3, 1]}, {"q": "8x² + 10x − 3 = (2x − A)(Bx + C) теңдігі орындалатындай A, B, C сандары оң сандар. Келесі өрнектерді дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A) 4A + BC", "B) AB + C"], "options": ["6", "8", "26", "24"], "pairs": [2, 1]}, {"q": "ABCD теңбүйірлі трапецияның табандары 8 см және 18 см. Трапецияға іштей сызылған шеңбер радиусын және трапецияның бүйір қабырғасын дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A) r", "B) бүйір қабырғасы"], "options": ["6", "12", "18", "13"], "pairs": [0, 3]}, {"q": "Геометриялық прогрессияның бірінші мүшесі 4-ке тең және b₂, b₃ – оң сандар. Егер екінші мүшесін 8-ге арттырсақ, онда олар арифметикалық прогрессияның мүшелері болады. Арифметикалық прогрессия айырымын және үшінші мүшесін дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A) d", "B) b₃"], "options": ["8", "24", "16", "36"], "pairs": [2, 3]}, {"q": "Радиустары 4 және 13-ке тең шарлар қиылысады. Егер олардың центрлерінің арақашықтығы 15-ке тең болса, қиылысқанда пайда болған қиманың ауданы мен ұзындығын дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A) C", "B) S"], "options": ["2,56π", "6,4π", "1,6π", "10,24π"], "pairs": [1, 3]}, {"q": "2sin²x + cosx = 1 теңдеуді шешіңіз", "options": ["A) x = 2πn, n∈Z", "B) x = ±π/3 + 2πk, k∈Z", "C) x = π/2 + πn, n∈Z", "D) x = ±2π/3 + 2πk, k∈Z", "E) x = ±π/4 + 2πk, k∈Z", "F) x = ±π/6 + 2πk, k∈Z"], "answers": [0, 3]}, {"q": "A(2; 0; 0), B(0; 3; 0), C(0; 0; 4), D(2; 3; 4) нүктелері берілген. ABC жазықтығынан D нүктесіне дейінгі қашықтықты табыңыз", "options": ["A) 36/√61", "B) 24/√61", "C) 36√61/61", "D) 25", "E) 36", "F) 24√61/61"], "answers": [1, 5]}, {"q": "SABCD – дұрыс төртбұрышты пирамида берілген. Егер ACS – қабырғасы a-ға тең дұрыс үшбұрыш болса, пирамида биіктігін және көлемін табыңыз", "options": ["A) a³√3/12", "B) a³/(6√2)", "C) a√3/2", "D) a³√2/12", "E) a³/(4√3)", "F) a√2/3"], "answers": [0, 2, 4], "img": "img/math/v2_38.jpg"}, {"q": "∫ₓ²ˣ (2t − 4) dt = 0 теңдеуінің түбірлерінің қосындысын табыңыз", "options": ["A) 1 2/3", "B) 1,(4)", "C) 4/3", "D) 1,(3)", "E) 5/3", "F) 1 1/3"], "answers": [2, 3, 5]}, {"q": "log₂³(125x³) = 27·log₂(5x) теңдеудің түбір(-лер)ін табыңыз", "options": ["A) 1/5", "B) 1/10", "C) 3/5", "D) −1/10", "E) 2/5", "F) 4/5"], "answers": [0, 1, 4]}]'::jsonb, now() + interval '1 second');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, 'Нұсқа 3 · Кеселер', '[{"q": "Өрнектің мәнін стандарт түрге келтіріңіз: (6,7·10⁴) + (3,4·10⁻²)", "options": ["A) 6,7000034·10⁴", "B) 6,6999966·10⁴", "C) 6,6884934·10⁴", "D) 6,6998834·10⁴"], "answer": 0}, {"q": "(x² − 3y)/(x + √(3y)) + √(3y) өрнегін ықшамдаңыз", "options": ["A) x", "B) √(3y)", "C) −√(3y)", "D) x − 2√(3y)"], "answer": 0}, {"q": "Тіктөртбұрыш пішіндес ауланы қоршау үшін ұзындығы 32 м сым қажет. Ауланың ауданының ең үлкен мәнін табыңыз", "options": ["A) 48", "B) 32", "C) 64", "D) 72"], "answer": 2}, {"q": "log₇(1/7ˣ + 6) − x − 1 = 0 теңдеуінің шешімі жатқан аралықты табыңыз", "options": ["A) (2; 4)", "B) (1; 3)", "C) (0; 2)", "D) (−1; 1)"], "answer": 3}, {"q": "Теңдеуді шешіңіз: (x² − 17x + 45)² − 8(x² − 17x + 45) − 105 = 0", "options": ["A) 2; 4; 15; 17", "B) 2; 4; 13; 15", "C) 2; 7; 13; 17", "D) 2; 7; 13; 15"], "answer": 1}, {"q": "sin x ≥ 3√3/5 теңсіздігін шешіңіз", "options": ["A) [arcsin(3√3/5) + 2πk; π − arcsin(3√3/5) + 2πk]", "B) [−π − arcsin(3√3/5) + 2πk; arcsin(3√3/5) + 2πk]", "C) шешімі жоқ", "D) [arcsin(3√3/5) + πk; π − arcsin(3√3/5) + πk]"], "answer": 2}, {"q": "sin α = 7/8-ге тең болса, cos α мәнін анықтаңыз, мұндағы 0° < α < 90°", "options": ["A) √8/8", "B) √15/8", "C) 5/8", "D) √17/8"], "answer": 1}, {"q": "(3 − 2a)/(a + 1) + a/(a + 1) : a/(a² − 1) − (2 − 3a)/(a + 1) өрнегін ықшамдаңыз", "options": ["A) a + 1", "B) a", "C) 1", "D) −a + 1"], "answer": 1}, {"q": "√(2x + 3) − √(x − 1) > 1 теңсіздігін шешіңіз", "options": ["A) (−1,5; +∞)", "B) [1; +∞)", "C) (1; +∞)", "D) (1; 7)"], "answer": 1}, {"q": "A(−1; 3) және B(2; 5) нүктелері арқылы өтетін түзудің теңдеуін табыңыз", "options": ["A) y = −(2/3)x + 3⅔", "B) y = (2/3)x + 2⅔", "C) y = (2/3)x + 3⅔", "D) y = (2/3)x + 4⅔"], "answer": 2}, {"q": "3x − 1 = 2(y + 3) және 0,5(6x − 1) = y − 9,5 түзулерінің қиылысу нүктесі координаталық жүйенің қай ширегінде жататынын табыңыз", "options": ["A) III", "B) II", "C) IV", "D) I"], "answer": 0}, {"q": "Төменде берілген графиктің теңдеуін табыңыз", "options": ["A) y = √(x − 3) + 2", "B) y = √(3 − x) + 2", "C) y = −√(3 − x) + 2", "D) y = −√(x − 3) + 2"], "answer": 2, "img": "img/math/v3_12.jpg"}, {"q": "y = x³ − 6x² + 9x + 2 функциясының [2; 3] аралығындағы ең үлкен және ең кіші мәндерін табыңыз", "options": ["A) 4 пен 2", "B) 5 пен 2", "C) 3 пен 1", "D) 3 пен 2"], "answer": 0}, {"q": "Мүшелері оң болатын геометриялық прогрессияның екінші мүшесі 16, үшінші және төртінші мүшелерінің қосындысы 5-ке тең. Бірінші және бесінші мүшелерінің қосындысын табыңыз", "options": ["A) 37,75", "B) 64,25", "C) 48,75", "D) 27,25"], "answer": 1}, {"q": "Теңдеуді шешіңіз: sin(0,1x)·cos(0,1x) = 1/2", "options": ["A) 0,5π + 10πn, n∈Z", "B) 2,5π + 2πn, n∈Z", "C) 2,5π + 5πn, n∈Z", "D) 2,5π + 10πn, n∈Z"], "answer": 3}, {"q": "log₍ₓ₊₅₎(3x² + 14x − 3) · log₍ₓ₊₃₎(x + 5) = 2 теңдеуінің түбірі жатқан аралықты табыңыз", "options": ["A) (1; 2)", "B) (1,5; 2,2)", "C) (1,4; 2,6)", "D) (0; 1)"], "answer": 0}, {"q": "∫ dx / x⁻² интегралын есептеңіз", "options": ["A) x⁴/4 + C", "B) −x³/3 + C", "C) x³/3 + C", "D) x²/2 + C"], "answer": 2}, {"q": "a⃗(√2; 2; −√2) және b⃗(−3; 0; 3) векторларының арасындағы бұрышты табыңыз", "options": ["A) 60°", "B) 45°", "C) 135°", "D) 150°"], "answer": 2}, {"q": "Дұрыс жетібұрышты призманың табан ауданы 13 см², ал бір бүйір жағының ауданы 21 см². Призманың толық бетінің ауданын табыңыз", "options": ["A) 34 см²", "B) 160 см²", "C) 173 см²", "D) 47 см²"], "answer": 2}, {"q": "y = sin⁶x + cos⁶x функциясының экстремум нүктелерін табыңыз", "options": ["A) x_max = π/4 + πn/2, x_min = πn/2", "B) x_max = πn/2, x_min = π/4 + πn/2", "C) x_max = πn, x_min = π/2 + πn", "D) экстремум нүктелері жоқ"], "answer": 1}, {"q": "(x₀; y₀) сандар жұбы { log₂x − log₂y = 2 ; (log₂x)² + (log₂y)² = 20 } теңдеулер жүйесінің бүтін шешімдері болса, x₀·y₀ мәнін табыңыз", "options": ["A) 24", "B) 48", "C) 32", "D) 64"], "answer": 3}, {"q": "{ 4x − x² ≥ 0 ; (x − 2)² > 1 } теңсіздігін шешіңіз", "options": ["A) x ∈ [0; 1) ∪ (3; 4]", "B) x ∈ (0; 1) ∪ (3; 4)", "C) x ∈ (−∞; 1) ∪ (3; +∞)", "D) x ∈ (−∞; 0] ∪ [4; +∞)"], "answer": 0}, {"q": "Есептеңіз: (2²·5³·13 + 26²·2³·5⁵) / (1 + 2³·13·5²)", "options": ["A) 6500", "B) 6200", "C) 6000", "D) 6700"], "answer": 0}, {"q": "y = √(−x² + x + 2) функцияның мәндер жиынын табыңыз", "options": ["A) (0; 1,5)", "B) (−∞; 1,5)", "C) [1,5; +∞)", "D) [0; 1,5]"], "answer": 3}, {"q": "Радиусы 7, биіктігі 8 болатын цилиндрдің толық бетінің ауданын табыңыз", "options": ["A) 105π", "B) 210π", "C) 112π", "D) 98π"], "answer": 1}, {"q": "Мәтін (№26–30, Кеселер): Мектеп асханасында суретте көрсетілгендей бірінші асқа арналған 635 кесе бар. Сабақ болатын күндері үлкен үзілісте әр сыныптан бір кезекші тағайындалып, дастарханды ас ішуге даярлайды. Бастауыш сыныптан кезекші 2 кеседен, орта буыннан кезекші 5 кеседен, ал жоғары сыныптан кезекші 7 кеседен тасиды. (Суретте: 5 кесе қабаттаса – 20 см, 2 кесе – 11 см)\n\nБір кесенің биіктігін анықтаңыз", "options": ["A) 7 см", "B) 9 см", "C) 8 см", "D) 10 см"], "answer": 2, "img": ["img/math/v3_ctx.jpg"]}, {"q": "Мәтін (№26–30, Кеселер): Мектеп асханасында суретте көрсетілгендей бірінші асқа арналған 635 кесе бар. Сабақ болатын күндері үлкен үзілісте әр сыныптан бір кезекші тағайындалып, дастарханды ас ішуге даярлайды. Бастауыш сыныптан кезекші 2 кеседен, орта буыннан кезекші 5 кеседен, ал жоғары сыныптан кезекші 7 кеседен тасиды. (Суретте: 5 кесе қабаттаса – 20 см, 2 кесе – 11 см)\n\nСуреттегідей жинақталған 3 кесенің биіктігін табыңыз", "options": ["A) 15 см", "B) 14 см", "C) 13 см", "D) 12 см"], "answer": 1, "img": ["img/math/v3_ctx.jpg"]}, {"q": "Мәтін (№26–30, Кеселер): Мектеп асханасында суретте көрсетілгендей бірінші асқа арналған 635 кесе бар. Сабақ болатын күндері үлкен үзілісте әр сыныптан бір кезекші тағайындалып, дастарханды ас ішуге даярлайды. Бастауыш сыныптан кезекші 2 кеседен, орта буыннан кезекші 5 кеседен, ал жоғары сыныптан кезекші 7 кеседен тасиды. (Суретте: 5 кесе қабаттаса – 20 см, 2 кесе – 11 см)\n\nБиіктігі 1 метр сөреге ең көп дегенде неше кесе сыйдыруға болады", "options": ["A) 31", "B) 30", "C) 29", "D) 32"], "answer": 0, "img": ["img/math/v3_ctx.jpg"]}, {"q": "Мәтін (№26–30, Кеселер): Мектеп асханасында суретте көрсетілгендей бірінші асқа арналған 635 кесе бар. Сабақ болатын күндері үлкен үзілісте әр сыныптан бір кезекші тағайындалып, дастарханды ас ішуге даярлайды. Бастауыш сыныптан кезекші 2 кеседен, орта буыннан кезекші 5 кеседен, ал жоғары сыныптан кезекші 7 кеседен тасиды. (Суретте: 5 кесе қабаттаса – 20 см, 2 кесе – 11 см)\n\nБастауыш сынып кезекшісі кеселерді 109 рет, жоғары сынып кезекшісі 31 рет тасыды. Егер олар барлық кеселерді тасып бітіру керек болса, орта буын кезекшісі кеселерді неше рет тасу керек", "options": ["A) 39", "B) 37", "C) 41", "D) 40"], "answer": 3, "img": ["img/math/v3_ctx.jpg"]}, {"q": "Мәтін (№26–30, Кеселер): Мектеп асханасында суретте көрсетілгендей бірінші асқа арналған 635 кесе бар. Сабақ болатын күндері үлкен үзілісте әр сыныптан бір кезекші тағайындалып, дастарханды ас ішуге даярлайды. Бастауыш сыныптан кезекші 2 кеседен, орта буыннан кезекші 5 кеседен, ал жоғары сыныптан кезекші 7 кеседен тасиды. (Суретте: 5 кесе қабаттаса – 20 см, 2 кесе – 11 см)\n\nАсханадағы барлық кесені ендері өзара тең, ал биіктіктері суретте көрсетілгендей сөрелерге орналастыру қажет болса, кемінде неше кесе сыймай қалатынын табыңыз", "options": ["A) 340", "B) 365", "C) 395", "D) 380"], "answer": 1, "img": ["img/math/v3_ctx.jpg", "img/math/v3_30.jpg"]}, {"q": "1 + 1/5 + 1/100 + 3(1/10³ + 1/10⁵ + 1/10⁷ + …) + 2(1/10⁴ + 1/10⁶ + 1/10⁸ + …) өрнегін ықшамдап, мәнін ондық бөлшек түріне келтіргеннен соң төмендегі мәндерді дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A) ондық бөлшектің периоды", "B) ондық бөлшектің периоды мен бүтін бөлігінің айырымы"], "options": ["32", "31", "30", "29"], "pairs": [0, 1]}, {"q": "g(x) = x² + 5, f(x) = (x − 1)² функциялары берілген. h(x) = f(g(x)) болса, төмендегі мәндерді дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A) h(−2)", "B) h(1)"], "options": ["64", "49", "25", "36"], "pairs": [0, 2]}, {"q": "(2a² + 4a − 30)/(−a² − 4a + 21) өрнегі берілген. Сәйкестендіріңіз", "left": ["A) a = −9 болғандағы өрнектің мәні", "B) Айнымалының мүмкін мәндер жиынына жатпайтын мәндердің көбейтіндісі"], "options": ["−4", "4", "−21", "24"], "pairs": [0, 2]}, {"q": "3/(x² + 9x + 18) + (2x + 7)/(x² + 5x − 6) − 1/(x + 3) = 0 теңдеуін шешіп, төмендегі мәндерді дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A) егер теңдеудің түбірі x₀ болса, x₀ + 11 мәні", "B) теңдеудің барлық нақты түбірлерінің саны"], "options": ["4", "3", "2", "1"], "pairs": [1, 3]}]'::jsonb, now() + interval '2 second');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, 'Нұсқа 4 · Есік дизайны', '[{"q": "y = 1 − 3x функциясының өсу аралығын табыңыз", "options": ["A) (−∞; 1/3)", "B) (−∞; +∞)", "C) (1; +∞)", "D) өсу аралықтары жоқ"], "answer": 3}, {"q": "√3·cos(−1 5π/6) есептеңіз", "options": ["A) 0,5", "B) 2", "C) 1,5", "D) 2/3"], "answer": 2}, {"q": "Суретте көрсетілген радиусы 3√3-ке тең дөңгелекке дұрыс алтыбұрыш сырттай сызылған. Боялған бөліктің ауданын табыңыз (π ≈ 3), √3 ≈ 1,7", "options": ["A) 4", "B) 3,6", "C) 3", "D) 4,2"], "answer": 1, "img": "img/math/v4_03.jpg"}, {"q": "Үшбұрышты призманың бүйір қырлары арқылы суретте көрсетілгендей қима жүргізілген. Пайда болған призма бөліктерінің көлемдерінің қатынасын табыңыз", "options": ["A) 4/3", "B) 13/3", "C) 13/11", "D) 11/3"], "answer": 2, "img": "img/math/v4_04.jpg"}, {"q": "sin(π/3 − x) = 1/2 теңдеуін шешіңіз", "options": ["A) x = (−1)ⁿ·π/6 + π/3 + πn, n∈Z", "B) x = (−1)ⁿ⁺¹·π/6 + πn, n∈Z", "C) x = (−1)ⁿ⁺¹·π/6 + π/3 + πn, n∈Z", "D) x = (−1)ⁿ·π/6 + π/3 + 2πn, n∈Z"], "answer": 2}, {"q": "L нүктесі CC₁ қырының ортасы. AL⃗ векторын m⃗, n⃗, p⃗ векторлары арқылы өрнектеңіз", "options": ["A) ½m⃗ + n⃗ + p⃗", "B) ½m⃗ − n⃗ − p⃗", "C) m⃗ + ½n⃗ + ½p⃗", "D) −½m⃗ + n⃗ + p⃗"], "answer": 0, "img": "img/math/v4_06.jpg"}, {"q": "(2 − √3)^(x² − 2x − 1) = 4(2 + √3) − (2 + √3)^(x² − 2x + 1) теңдеудің ең үлкен және ең кіші түбірлерін жауаптарымен сәйкестендіріңіз", "left": ["A) ең үлкен түбірі", "B) ең кіші түбірі"], "options": ["−1", "1 + √2", "1", "1 − √2"], "pairs": [1, 3]}, {"q": "Шексіз кемімелі геометриялық прогрессияның тақ мүшелерінің қосындысы 80/247, ал жұп мүшелерінің қосындысы 15/247-ке тең. Прогрессияның бірінші мүшесі мен еселігін жауаптарымен сәйкестендіріңіз", "left": ["A) b₁", "B) q"], "options": ["1/16", "1/6", "3/16", "5/16"], "pairs": [3, 2]}, {"q": "y = |1 − 5x|, x = 0, x = 2 сызықтарымен шектелген фигура ауданын табыңыз", "options": ["A) 41/5", "B) 6 1/5", "C) 6,2", "D) 8 1/5", "E) 31/5", "F) 8,2"], "answers": [0, 3, 5]}, {"q": "{ sinx·cosy = 1/3 ; siny·cosx = 1/6 } теңдеулер жүйесін шешіп, 90° ≤ x + y ≤ 180° шартын қанағаттандыратындай x + y мәнін табыңыз", "options": ["A) 135°", "B) 5π/6", "C) 3π/4", "D) 150°", "E) 120°", "F) 2π/3"], "answers": [1, 3]}, {"q": "Дұрыс алтыбұрышты призманы көрсетілген жазықтықтармен қиғанда пайда болған денелердің көлемі бола алатын мәнд(-ерд)і табыңыз", "options": ["A) 81√3", "B) 54√3", "C) 108√3", "D) 9√3", "E) 27√3", "F) 36√3"], "answers": [1, 2], "img": "img/math/v4_11.jpg"}, {"q": "logₓ2 · log₂ₓ2 · log₂(16x) ≥ 1 теңсіздігінің ең кіші және ең үлкен натурал мәндерін табыңыз", "options": ["A) 1/4", "B) 1", "C) 0", "D) 2", "E) 4", "F) 3"], "answers": [3, 4]}, {"q": "Суретте көрсетілген сектордың центрлік бұрышы 100°-қа тең. CD = 18, DE = 36. Сектордың боялған бөлігінен қиық конус жасалды. Қиық конустың бүйір беті мен толық бетінің ауданын табыңыз", "options": ["A) 1000π", "B) 720π", "C) 360π", "D) 970π", "E) 1440π", "F) 540π"], "answers": [1, 3], "img": "img/math/v4_13.jpg"}, {"q": "Мәтін (№26–30, Есік дизайны): Дизайнер есік бетіне шеңберлер мен гүл жапырақшаларынан тұратын геометриялық ою-өрнек салды. Сол жақтағы суретте көрсетілгендей, центрі координаталар басында жатқан үлкен шеңбердің ішіне радиустары осы шеңбердің радиусына тең және центрлері шеңбер бойында орналасқан доғалар көмегімен 6 жапырақшадан тұратын сары түсті гүл салынған. Үлкен шеңбердің радиусы R = 4 см-ге тең. Оң жақтағы кіші шеңбер мен оның ішіндегі гүл үлкен шеңберді k = 1/2 ұқсастық коэффициентімен кішірейту (гомотетия) арқылы алынған. Шеңбер бойындағы A, B, C, D, E, F нүктелері жапырақшалардың ұштары болып табылады және шеңберді 6 тең бөлікке бөледі.\n\nFC⃗ векторының ұзындығын табыңыз", "img": "img/math/v4_ctx.jpg", "options": ["A) 4", "B) 10", "C) 8", "D) 6"], "answer": 2}, {"q": "Мәтін (№26–30, Есік дизайны): Дизайнер есік бетіне шеңберлер мен гүл жапырақшаларынан тұратын геометриялық ою-өрнек салды. Сол жақтағы суретте көрсетілгендей, центрі координаталар басында жатқан үлкен шеңбердің ішіне радиустары осы шеңбердің радиусына тең және центрлері шеңбер бойында орналасқан доғалар көмегімен 6 жапырақшадан тұратын сары түсті гүл салынған. Үлкен шеңбердің радиусы R = 4 см-ге тең. Оң жақтағы кіші шеңбер мен оның ішіндегі гүл үлкен шеңберді k = 1/2 ұқсастық коэффициентімен кішірейту (гомотетия) арқылы алынған. Шеңбер бойындағы A, B, C, D, E, F нүктелері жапырақшалардың ұштары болып табылады және шеңберді 6 тең бөлікке бөледі.\n\nГүлдің A нүктесіндегі жапырағы C нүктесіндегі жапыраққа сағат тілімен айналып, беттескенде неше градусқа бұрылатынын табыңыз", "img": "img/math/v4_ctx.jpg", "options": ["A) 60°", "B) 120°", "C) 180°", "D) 240°"], "answer": 1}, {"q": "Мәтін (№26–30, Есік дизайны): Дизайнер есік бетіне шеңберлер мен гүл жапырақшаларынан тұратын геометриялық ою-өрнек салды. Сол жақтағы суретте көрсетілгендей, центрі координаталар басында жатқан үлкен шеңбердің ішіне радиустары осы шеңбердің радиусына тең және центрлері шеңбер бойында орналасқан доғалар көмегімен 6 жапырақшадан тұратын сары түсті гүл салынған. Үлкен шеңбердің радиусы R = 4 см-ге тең. Оң жақтағы кіші шеңбер мен оның ішіндегі гүл үлкен шеңберді k = 1/2 ұқсастық коэффициентімен кішірейту (гомотетия) арқылы алынған. Шеңбер бойындағы A, B, C, D, E, F нүктелері жапырақшалардың ұштары болып табылады және шеңберді 6 тең бөлікке бөледі.\n\nКіші шеңбердің ішіндегі сары түсті гүлдің жалпы ауданын табыңыз", "img": "img/math/v4_ctx.jpg", "options": ["A) 8π − 12√3 см²", "B) 16π − 4√3 см²", "C) 4π − 2√3 см²", "D) 4π − √3 см²"], "answer": 0}, {"q": "Мәтін (№26–30, Есік дизайны): Дизайнер есік бетіне шеңберлер мен гүл жапырақшаларынан тұратын геометриялық ою-өрнек салды. Сол жақтағы суретте көрсетілгендей, центрі координаталар басында жатқан үлкен шеңбердің ішіне радиустары осы шеңбердің радиусына тең және центрлері шеңбер бойында орналасқан доғалар көмегімен 6 жапырақшадан тұратын сары түсті гүл салынған. Үлкен шеңбердің радиусы R = 4 см-ге тең. Оң жақтағы кіші шеңбер мен оның ішіндегі гүл үлкен шеңберді k = 1/2 ұқсастық коэффициентімен кішірейту (гомотетия) арқылы алынған. Шеңбер бойындағы A, B, C, D, E, F нүктелері жапырақшалардың ұштары болып табылады және шеңберді 6 тең бөлікке бөледі.\n\nҮлкен шеңбердің ішіндегі қызыл түсті аймақтың ауданын табыңыз", "img": "img/math/v4_ctx.jpg", "options": ["A) 24√3 − 16π см²", "B) 48√3 − 16π см²", "C) 16π − 4√3 см²", "D) 32π − 48√3 см²"], "answer": 1}, {"q": "Мәтін (№26–30, Есік дизайны): Дизайнер есік бетіне шеңберлер мен гүл жапырақшаларынан тұратын геометриялық ою-өрнек салды. Сол жақтағы суретте көрсетілгендей, центрі координаталар басында жатқан үлкен шеңбердің ішіне радиустары осы шеңбердің радиусына тең және центрлері шеңбер бойында орналасқан доғалар көмегімен 6 жапырақшадан тұратын сары түсті гүл салынған. Үлкен шеңбердің радиусы R = 4 см-ге тең. Оң жақтағы кіші шеңбер мен оның ішіндегі гүл үлкен шеңберді k = 1/2 ұқсастық коэффициентімен кішірейту (гомотетия) арқылы алынған. Шеңбер бойындағы A, B, C, D, E, F нүктелері жапырақшалардың ұштары болып табылады және шеңберді 6 тең бөлікке бөледі.\n\nКіші шеңбердің ұзындығын табыңыз", "img": "img/math/v4_ctx.jpg", "options": ["A) 2π см", "B) 4π см", "C) 8π см", "D) 16π см"], "answer": 1}]'::jsonb, now() + interval '3 second');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, 'Нұсқа 5 · Құрылыс материалдары', '[{"q": "(x − 3)(x + 3)√(x − 2) < 0 теңсіздігін шешіңіз", "options": ["A) [2; 3)", "B) (−∞; −3) ∪ (2; 3)", "C) (2; 3)", "D) (3; +∞)"], "answer": 2}, {"q": "(x₀; y₀) сандар жұбы { logₓ(9x + 7y) = 2 ; log_y(9y + 7x) = 2 } теңдеулер жүйесінің шешімі болса, (x₀ + y₀)/16 өрнегінің мәнін табыңыз", "options": ["A) 2", "B) 1", "C) 16", "D) 32"], "answer": 0}, {"q": "ABCDA₁B₁C₁D₁ кубының қыры 1-ге тең. sin²α + sin²β + sin²γ мәнін табыңыз", "options": ["A) 4/3", "B) √3/2", "C) 3", "D) 2"], "answer": 3, "img": "img/math/v5_03.jpg"}, {"q": "(7m + 2)² − (7m − 2)² өрнегі 12-ге бөлінетіндей ең кіші натурал m мен 70-ке бөлінетіндей ең кіші натурал m сандарының қосындысын табыңыз", "options": ["A) 8", "B) 5", "C) 6", "D) 7"], "answer": 0}, {"q": "25ˣ − 2ˣ·12 − 6,25·(0,16)ˣ = 0 теңдеуінің бүтін түбірлерінің санын табыңыз", "options": ["A) 1", "B) 2", "C) 3", "D) 4"], "answer": 0}, {"q": "Тікбұрышты үшбұрыштың тік бұрышының биссектрисасы гипотенузаны 15 және 20-ға тең кесінділерге бөледі. Кіші катетті табыңыз", "options": ["A) 19", "B) 21", "C) 23", "D) 28"], "answer": 1}, {"q": "f(x) = 3x + 4, g(x) = 2x + 5, h(x) = x − 2 болса, f(g(h(x))) = 0 теңдеуін шешіңіз", "options": ["A) −6/7", "B) −3 1/6", "C) −1 2/5", "D) −1 1/6"], "answer": 3}, {"q": "Центрі O(−1; 4; 8) нүктесінде орналасқан сфераға M(2; 4; 9) нүктесінде жүргізілген жанама жазықтықтың теңдеуін жазыңыз", "options": ["A) 3x + y + z − 14 = 0", "B) 3x + z − 15 = 0", "C) 2x + 4y + 9z − 15 = 0", "D) 3x + z − 5 = 0"], "answer": 1}, {"q": "∫₁² 3ˣ·ln3 dx + ∫₃⁴ 5ˣ·ln5 dx есептеңіз", "options": ["A) 593", "B) 606", "C) 526", "D) 506"], "answer": 3}, {"q": "8ˣ + 5·2^(x+2) + 32 = 11·4ˣ теңдеуінің түбірлерінің қосындысын табыңыз", "options": ["A) 3", "B) 7", "C) 5", "D) 4"], "answer": 2}, {"q": "Мәтін (№26–30, Құрылыс материалдары): Құрылыс жұмыстарын жүргізу барысында төмендегідей геометриялық пішіндегі материалдар жиі қолданылады. Суретте ұзындығы 2,4 м, ені 1,25 м болатын жалпақ қаңылтыр, биіктігі 48 см, диаметрі 30 см конус тәріздес қызыл шелек, диаметрі 50 мм, ұзындығы 1,2 м цилиндр тәріздес құбыр және ұзындығы 80 см, ені 40 см, биіктігі 15 см болатын параллелепипед тәріздес қорап берілген. 1 м²-қа 1 құты бояу жұмсалады. (π ≈ 3)\n\nБір қораптың сыйымдылығын табыңыз", "options": ["A) 0,0048 м³", "B) 0,135 м³", "C) 0,0135 м³", "D) 0,048 м³"], "answer": 3, "img": "img/math/v5_ctx.jpg"}, {"q": "Мәтін (№26–30, Құрылыс материалдары): Құрылыс жұмыстарын жүргізу барысында төмендегідей геометриялық пішіндегі материалдар жиі қолданылады. Суретте ұзындығы 2,4 м, ені 1,25 м болатын жалпақ қаңылтыр, биіктігі 48 см, диаметрі 30 см конус тәріздес қызыл шелек, диаметрі 50 мм, ұзындығы 1,2 м цилиндр тәріздес құбыр және ұзындығы 80 см, ені 40 см, биіктігі 15 см болатын параллелепипед тәріздес қорап берілген. 1 м²-қа 1 құты бояу жұмсалады. (π ≈ 3)\n\nБір-біріне жалғанып тұрған 12 құбырға су жіберіліп, құбырлар толықтай суға толды. Судың көлемін табыңыз", "options": ["A) 0,0027 м³", "B) 0,27 м³", "C) 0,027 м³", "D) 0,108 м³"], "answer": 2, "img": "img/math/v5_ctx.jpg"}, {"q": "Мәтін (№26–30, Құрылыс материалдары): Құрылыс жұмыстарын жүргізу барысында төмендегідей геометриялық пішіндегі материалдар жиі қолданылады. Суретте ұзындығы 2,4 м, ені 1,25 м болатын жалпақ қаңылтыр, биіктігі 48 см, диаметрі 30 см конус тәріздес қызыл шелек, диаметрі 50 мм, ұзындығы 1,2 м цилиндр тәріздес құбыр және ұзындығы 80 см, ені 40 см, биіктігі 15 см болатын параллелепипед тәріздес қорап берілген. 1 м²-қа 1 құты бояу жұмсалады. (π ≈ 3)\n\nСыйымдылығы 200 литр ыдысты сумен толтыру үшін қызыл шелекпен кемінде неше рет су тасу керек?", "options": ["A) 18", "B) 19", "C) 7", "D) 20"], "answer": 1, "img": "img/math/v5_ctx.jpg"}, {"q": "Мәтін (№26–30, Құрылыс материалдары): Құрылыс жұмыстарын жүргізу барысында төмендегідей геометриялық пішіндегі материалдар жиі қолданылады. Суретте ұзындығы 2,4 м, ені 1,25 м болатын жалпақ қаңылтыр, биіктігі 48 см, диаметрі 30 см конус тәріздес қызыл шелек, диаметрі 50 мм, ұзындығы 1,2 м цилиндр тәріздес құбыр және ұзындығы 80 см, ені 40 см, биіктігі 15 см болатын параллелепипед тәріздес қорап берілген. 1 м²-қа 1 құты бояу жұмсалады. (π ≈ 3)\n\n50 шелектің сыртын қызылға бояу үшін неше құты бояу жұмсалады?", "options": ["A) 34", "B) 15", "C) 11", "D) 12"], "answer": 3, "img": "img/math/v5_ctx.jpg"}, {"q": "Мәтін (№26–30, Құрылыс материалдары): Құрылыс жұмыстарын жүргізу барысында төмендегідей геометриялық пішіндегі материалдар жиі қолданылады. Суретте ұзындығы 2,4 м, ені 1,25 м болатын жалпақ қаңылтыр, биіктігі 48 см, диаметрі 30 см конус тәріздес қызыл шелек, диаметрі 50 мм, ұзындығы 1,2 м цилиндр тәріздес құбыр және ұзындығы 80 см, ені 40 см, биіктігі 15 см болатын параллелепипед тәріздес қорап берілген. 1 м²-қа 1 құты бояу жұмсалады. (π ≈ 3)\n\nЖалпақ бір қаңылтырдан неше қорап жасауға болады?", "options": ["A) 5", "B) 2", "C) 3", "D) 4"], "answer": 2, "img": "img/math/v5_ctx.jpg"}, {"q": "x|x| − 5|x| + 6 = 0 теңдеуінің x > 0 және x < 0 болғандағы шешімдерінің үлкенін дұрыс жауаптарымен сәйкестендіріңіз", "left": ["x > 0", "x < 0"], "options": ["A) −1", "B) 2", "C) 3", "D) 6"], "pairs": [2, 0]}, {"q": "6x² − 85x + 300 = (2x − A)(Bx + C) теңдігі орындалатындай A, B, C сандары берілген. Келесі өрнектерді дұрыс жауаптарымен сәйкестендіріңіз", "left": ["A·B − C", "A + B·C"], "options": ["A) −45", "B) 65", "C) 75", "D) 85"], "pairs": [1, 0]}, {"q": "y = 2(x + 3)(x − a) функциясы берілген. Төмендегі сұрақтарды жауаптарымен сәйкестендіріңіз", "left": ["a-ның қандай мәнінде берілген функция жұп функция болады", "Жұп функцияның ең кіші мәні"], "options": ["A) −3", "B) 3", "C) −18", "D) 18"], "pairs": [1, 2]}, {"q": "x² − 8|x − 3| = 6x теңдеуін шешіп, төмендегі сұрақтарды жауаптарымен сәйкестендіріңіз", "left": ["Түбірлердің көбейтіндісі", "Түбірлердің қосындысы"], "options": ["A) −72", "B) −576", "C) 6", "D) 12"], "pairs": [0, 2]}, {"q": "(x₀; y₀) сандар жұбы { √((x − y)/(x + y)) + √((x + y)/(x − y)) = 5/2 ; x² + y² = 34 } теңдеулер жүйесінің шешімі болса, |x₀ − y₀| мәні жатқан аралықт(-ард)ы табыңыз", "options": ["A) (1; 4]", "B) [5; 8)", "C) (0; 3)", "D) [4; 6]", "E) (7; 10)", "F) (2; 5)"], "answers": [0, 2, 4]}, {"q": "{ x − y = −π ; tgx·tgy = 1 } теңдеулер жүйесін шешіңіз", "options": ["A) (π/4 + πk; 5π/4 + πk), k ∈ Z", "B) (−π/4 + πk; 3π/4 + πk), k ∈ Z", "C) (−3π/4 + πk; π/4 + πk), k ∈ Z", "D) (3π/4 + πk; 7π/4 + πk), k ∈ Z", "E) (−π/4 + 2πk; 3π/4 + 2πk), k ∈ Z", "F) (π/4 + πk; 5π/4 + 2πk), k ∈ Z"], "answers": [0, 1, 2, 3]}, {"q": "{ √y + lg x² = 2 ; y + 4lg x = 28 } теңдеулер жүйесінің шешімі (x₀; y₀) болса, x₀⁻¹ − y₀ өрнегінің мәнін табыңыз", "options": ["A) −2⁵", "B) −32", "C) −15,999", "D) 2⁶", "E) −35,99", "F) 2³·17"], "answers": [3]}, {"q": "Табаны 2 және 6 болатын дұрыс үшбұрышты қиық пирамиданың бүйір қыры 8√21/3. Пирамиданың көлемі жатқан аралықт(-ард)ы табыңыз", "options": ["A) (81; 90)", "B) (79; 89)", "C) (95; 120)", "D) (70; 80)", "E) (90; 100)", "F) (80; 96)"], "answers": [4, 5]}]'::jsonb, now() + interval '4 second');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, 'Нұсқа 6 · Нағыз ҰБТ', '[{"q": "Жазыңқы бұрыштың 3/4 бөлігін радианмен жазыңыз", "options": ["A) 2π/3", "B) 5π/6", "C) 3π/2", "D) 3π/4"], "answer": 3}, {"q": "Шеңбердің AC хордасының ұзындығы 6√2-ге тең. AC хордасынан AB : BC = 5 : 1 болатындай B нүктесі алынды. Егер B нүктесінен шеңбер центріне дейінгі қашықтық √26 болса, шеңбер ұзындығын табыңыз", "options": ["A) 24π", "B) 6π", "C) 12π", "D) 36π"], "answer": 2}, {"q": "cos24° − 2sin42°·sin18° есептеңіз", "options": ["A) −1/2", "B) √3/2", "C) 1/2", "D) 0"], "answer": 2}, {"q": "5^((x+2)/2) + (√5)ˣ = 150 теңдеудің түбірі жататын аралықты табыңыз", "options": ["A) [−1; 2)", "B) (1; 4]", "C) (0; 3)", "D) (4; 7)"], "answer": 1}, {"q": "Жарты сфераның бет ауданын табыңыз", "options": ["A) 144π", "B) 72π", "C) 108π", "D) 76π"], "answer": 2, "img": "img/math/v6_05.jpg"}, {"q": "DEF доғасын керетін ішкі бұрыштарының қосындысы 120°-қа тең болса, ∠EDF бұрышын табыңыз. DE = EF", "options": ["A) 20°", "B) 40°", "C) 10°", "D) 30°"], "answer": 0, "img": "img/math/v6_06.jpg"}, {"q": "(x + 1)/(3x − 2) + (2x − 1)/(3x + 2) = A/(9x² − 4) теңдігі орындалатындай A-ның мүшелерін табыңыз", "options": ["A) 9x²", "B) 4", "C) −9x²", "D) 2x", "E) −4", "F) −2x"], "answers": [0, 1, 5]}, {"q": "a₁ = 92, a₅ = 60. Sₙ = 560 болса, n-нің қабылдайтын мән(-дер)і", "options": ["A) 14", "B) 12", "C) 8", "D) 10", "E) 7", "F) 20"], "answers": [0, 3]}, {"q": "y = 1 − |x| функциясы берілген. y-тің қабылдайтын мән(-дер)і", "options": ["A) 0", "B) 1", "C) 2", "D) 5", "E) 0,5", "F) 4"], "answers": [0, 1, 4]}, {"q": "Пирамиданың табанына параллель жазықтық пирамида биіктігін қақ бөледі. Пайда болған бөліктердің көлемдерінің қатынасын табыңыз", "options": ["A) 1:4", "B) 1:5", "C) 1:7", "D) 1:8", "E) 8:1", "F) 7:1"], "answers": [2, 5]}, {"q": "Параллелепипедтің жақтарының диагональдары √13, 5 және 2√5-ке тең. Параллелепипедтің диагоналін және көлемін табыңыз", "options": ["A) √58", "B) 28", "C) √29", "D) 20", "E) 24", "F) 2√10"], "answers": [2, 4], "img": "img/math/v6_11.jpg"}, {"q": "{ a₃·a₆ = 136 ; a₃ + a₄ + a₅ + a₆ = 50 } өспелі арифметикалық прогрессияның бірінші мүшесін және айырымын табыңыз", "options": ["A) 2", "B) 5", "C) 3", "D) 4", "E) 23", "F) −3"], "answers": [0, 2]}, {"q": "Тікбұрышты үшбұрыштың қабырғалары өзара арифметикалық прогрессия құрайды. Периметрі 18-ден аспайтын болса, ауданы қабылдауы мүмкін мәндерді табыңыз", "options": ["A) 12", "B) 14", "C) 13", "D) 20", "E) 18", "F) 10"], "answers": [0, 2, 5]}, {"q": "y = (8x − 3)/(2x − 5) функциясы берілген. Сәйкестендіріңіз", "left": ["E(y)", "D(y)"], "options": ["A) (−∞; −3) ∪ (−3; +∞)", "B) (−∞; 2) ∪ (2; +∞)", "C) (−∞; 2,5) ∪ (2,5; +∞)", "D) (−∞; 4) ∪ (4; +∞)"], "pairs": [3, 2]}, {"q": "(0,04)ˣ − 5^(x−1) = 0 теңдеуді шешіп, мәндерін сәйкестендіріңіз", "left": ["3x", "3⅓ − x"], "options": ["A) 3", "B) 1", "C) −1", "D) 4"], "pairs": [1, 0]}, {"q": "((9c² − b²)/(3c − b − 2) + 2(b + 3c)/(b + 2 − 3c))·(b + 2c) өрнекті ықшамдап, пайда болған көпмүшенің коэффициенттерінің қосындысын m және көпмүше дәрежесін n деп алып, (m − n) және (m + n) мәндерін дұрыс жауаптарымен сәйкестендіріңіз", "left": ["m + n", "m − n"], "options": ["A) 10", "B) 2", "C) 14", "D) 12"], "pairs": [2, 0]}, {"q": "Шексіз кемімелі геометриялық прогрессияның қосындысы 10. Ал мүшелерінің кубтарының қосындысы 16000/31. Сәйкестендіріңіз", "left": ["2·q⁻² + 3·b₁", "5·q⁻² − 8·b₁"], "options": ["A) 88", "B) 74", "C) 61", "D) 56"], "pairs": [1, 2]}, {"q": "y = −2026/(x + 4) функциясының графигіне тиісті A(−7; y) және B(4; y) нүктелері координаталар жазықтығының қай ширегінде орналасқан", "left": ["A(−7; y)", "B(4; y)"], "options": ["A) I", "B) II", "C) III", "D) IV"], "pairs": [1, 3]}, {"q": "Берілген Ax² + Bx + C = 0 квадрат теңдеуі үшін A > 0, B < 0, C > 0 және x₂ > x₁ шарттары орындалады. Сәйкестендіріңіз", "left": ["x₁ таңбасы", "x₂ таңбасы"], "options": ["A) x₁ < 0", "B) x₂ > 0", "C) x₁ > 0", "D) x₂ < 0"], "pairs": [2, 1]}, {"q": "Төбесі A(−2; −7) нүктесінде орналасқан y = kx² + 8x + m параболасының теңдеуіндегі k және m мәндерін дұрыс жауаптарымен сәйкестендіріңіз", "left": ["k", "m"], "options": ["A) 1", "B) −2", "C) 2", "D) −7"], "pairs": [2, 0]}]'::jsonb, now() + interval '5 second');
  insert into public.tests (subject, section, title, questions, created_at) values (sid, sec, 'Нұсқа 7 · ҰБТ 2027', '[{"q": "Есептеңіз: sin85° − sin25°", "options": ["A) √3·cos110°", "B) sin55°", "C) √3·sin55°", "D) cos55°"], "answer": 3}, {"q": "75x⁵y − 75x⁴y² + 80xy⁴ көпмүшесінің дәрежесін табыңыз", "options": ["A) 5", "B) 8", "C) 6", "D) 4"], "answer": 2}, {"q": "Қабырғалары 2 см және 4 см тіктөртбұрышпен теңшамалас шаршының периметрін табыңыз", "options": ["A) 8√2", "B) 6√2", "C) 8", "D) 12"], "answer": 0}, {"q": "Тікбұрышты үшбұрыштың катеттеріне жүргізілген медианалары 15 және 6√5-ке тең. Гипотенузаны табыңыз", "options": ["A) 19", "B) 15", "C) 18", "D) 16"], "answer": 2}, {"q": "∫₀^(π/2) 3/sin²(x + π/4) dx интегралының мәні", "options": ["A) 8", "B) 6", "C) 10", "D) 4"], "answer": 1}, {"q": "Дұрыс төртбұрышты призма табанының диагоналі 5 см, призма диагоналі 13 см. Призма көлемін табыңыз", "options": ["A) 150 см³", "B) 300 см³", "C) 150√2 см³", "D) 175,5 см³"], "answer": 0}, {"q": "log₂(27^(x−1) + 6) = log₂3 + log₂(3^(x+4) + 2) теңдеуінің бөлгіштерін табыңыз", "options": ["A) 1; 2", "B) 1; 2; 4", "C) 1; 5", "D) 1; 2; 3; 6"], "answer": 1}, {"q": "{ 7/√(x−7) − 4/√(y+6) = 5/3 ; 5/√(x−7) + 3/√(y+6) = 13/6 } теңдеулер жүйесінің түбірлері x, y бойынша x + y мәнін табыңыз", "options": ["A) 46", "B) 45", "C) 19", "D) 36"], "answer": 0}, {"q": "Табан аудандары 9π және 25π-ге тең қиық конусқа іштей сызылған сфера диаметрін табыңыз", "options": ["A) √55", "B) √15", "C) 4√6", "D) 2√15"], "answer": 3}, {"q": "a⃗ және b⃗ векторлары коллинеар емес. Егер |a⃗| = |b⃗| = 4 болса, (a⃗ + b⃗) және (a⃗ − b⃗) векторларының арасындағы бұрышты табыңыз", "options": ["A) 30°", "B) 60°", "C) 90°", "D) 120°"], "answer": 2}, {"q": "(4x − 1)/(x − 1) = k + 3 теңдеуінің түбірі теріс сан болатындай k-ның мәнін табыңыз", "options": ["A) (−∞; −2) ∪ (1; +∞)", "B) (−∞; −2)", "C) (1; +∞)", "D) (−2; 1)"], "answer": 3}, {"q": "Есептеңіз: sin(2arctg5)", "options": ["A) 1/3", "B) 5/13", "C) 7/13", "D) 10/11"], "answer": 1}, {"q": "{ 3ˣ·2ʸ = 972 ; x − y = 3 } теңдеулер жүйесінің шешімі бойынша xy мәнін табыңыз", "options": ["A) 12", "B) 8", "C) 10", "D) 14"], "answer": 2}, {"q": "2^(1 − log₂sinx) = 4 теңдеуін шешіңіз", "options": ["A) (−1)ⁿ·π/6 + πn, n ∈ Z", "B) (−1)ⁿ·π/3 + πn, n ∈ Z", "C) π/6 + 2πn, n ∈ Z", "D) (−1)ⁿ·π/6 + 2πn, n ∈ Z"], "answer": 0}, {"q": "y = x² + bx + c параболасына x₀ нүктесінде жүргізілген жанаманың теңдеуі y = 2 − 3x болса, b + c мәнін табыңыз", "options": ["A) −2", "B) −3", "C) 1", "D) −1"], "answer": 3}, {"q": "Арифметикалық прогрессияның бірінші мүшесі 120-ға, ал екінші мүшесі 108-ге тең болса, прогрессияның қосындысының ең үлкен мәнін табыңыз", "options": ["A) 660", "B) 792", "C) 780", "D) 600"], "answer": 0}, {"q": "Суретте табан радиусы 5-ке тең конустың бүйір бетінің жазбасы берілген. Конус көлемінің мәні", "options": ["A) 40√2π/3", "B) 80√3π/3", "C) 120√3π/3", "D) 250√2π/3"], "answer": 3, "img": "img/math/v7_17.jpg"}, {"q": "f(x) = (x − 1)²·∛((x − 1)⁴) функциясының туындысын табыңыз", "options": ["A) f′(x) = 10(x − 1)²·∛(x − 1) / 3", "B) f′(x) = 10·∛((x − 1)¹³) / 3", "C) f′(x) = 11(x − 1)·⁷√((x − 1)⁴) / 4", "D) f′(x) = 11(x − 1)·⁵√((x − 1)⁴) / 4"], "answer": 0}, {"q": "x² + 2|x| − 1 = 0 теңдеуінің түбірлерінің квадраттарының қосындысы", "options": ["A) 6", "B) 14", "C) 6 + 4√2", "D) 6 − 4√2"], "answer": 3}, {"q": "∫ sin5x·cos7x dx интегралын табыңыз", "options": ["A) (1/12)cos6x − (1/2)cosx + C", "B) (1/2)cos6x + (1/2)cosx + C", "C) −(1/24)cos12x + (1/4)cos2x + C", "D) −(1/2)cos6x + (1/2)cosx + C"], "answer": 2}, {"q": "A(3; 2; −3) және B(5; −4; 1) нүктелері берілген. λ = 1/2 қатынасындай AB кесіндісін бөлетін C нүктесінің координатасын табыңыз", "options": ["A) (11/3; 0; −5/3)", "B) (13/3; 0; 7/3)", "C) (3; 0; 2)", "D) (11/3; 1; 5/3)"], "answer": 0}]'::jsonb, now() + interval '6 second');
